INSERT INTO knowledge_facts (fact_text, category, verified, created_at) VALUES
  ('Foto: Marca El Celta visitará este jueves el estadio del PAOK de Salónica por primera vez en su historia, pero ya tiene experiencia en la ciudad helena, en la que jugó en 1999 una eliminatoria ante el eterno rival del PAOK, el Aris de Salónica, en la segunda ronda de la Copa de la UEFA', 'historia', TRUE, NOW()),
  ('El equipo entrenado por Víctor Fernández viajó a Grecia para medirse a uno de los equipos más importantes del país, y logró un empate a dos goles, que fue un tanto agridulce ya que Karpin adelantó a los célticos cerca del descanso con dos goles prácticamente consecutivos, el primero de ellos un golazo con un gran lanzamiento desde fuera del área', 'historia', TRUE, NOW()),
  ('Pero justo antes del descanso, Paulo Andrioli puso el 1-2, y en la segunda mitad igualó la contienda Kyzeridis, dejando un 2-2 que seguía siendo un buen resultado para los célticos, que resolvieron la eliminatoria en el partido de vuelta venciendo 2-0 en Balaídos', 'historia', TRUE, NOW()),
  ('Sería la eliminatoria previa a los históricos enfrentamientos ante Benfica y Juventus, resueltos con sendas goleadas inolvidables en Balaídos.', 'historia', TRUE, NOW()),
  ('Foto: RC Celta Un nuevo triunfo sirvió para cerrar una primera vuelta del Celta que ya es una de las mejores en la historia reciente del club celeste, mejor incluso que la del año pasado en la que acabó clasificándose para la Europa League', 'historia', TRUE, NOW()),
  ('Gran parte de este éxito se ha cimentado curiosamente en los partidos lejos de Balaídos', 'historia', TRUE, NOW()),
  ('El Celta se está mostrando esta campaña, y ya en el final de la anterior, como un equipo temible para cualquier equipo de la categoría', 'historia', TRUE, NOW()),
  ('El triunfo logrado ayer eleva hasta 18 los puntos que ha conseguido el Celta lejos de Balaídos en la primera vuelta, y según informa la cuenta de X, Afouteza e Corazón, se trata del récord histórico de puntos logrados como visitante en una primera vuelta por el equipo celeste, firmando esos 18 puntos en 9 partidos, lo que le sitúa además como el tercer mejor visitante de la categoría, solo superado por Barcelona (22) y Real Madrid (21), ambos con 10 encuentros fuera de casa por los 9 del Celta', 'historia', TRUE, NOW()),
  ('Son cifras absolutamente brutales que le sitúan incluso por encima del Villarreal, que es tercero en la clasificación a la estela de Barcelona y Madrid, y que ha logrado 16 puntos en la primera vuelta como visitante, aunque con tan solo 8 partidos, ya que tiene pendiente el duelo aplazado en su momento ante el Levante', 'historia', TRUE, NOW()),
  ('Brea / Faro de Vigo El Leganés visitará este sábado Balaídos, más de cinco años después de su última visita al recinto celeste', 'historia', TRUE, NOW()),
  ('A lo largo de la historia, vigueses y madrileños se han enfrentado tan solo cinco veces en Balaídos, pero el balance está bastante igualado', 'historia', TRUE, NOW()),
  ('El conjunto pepinero venció por la mínima (0-1) en sus dos primeros partidos en el recinto celeste', 'historia', TRUE, NOW()),
  ('La primera vez que el Leganés jugó en Balaídos fue en la Temporada 2000-01, en los octavos de final de la copa del Rey, aunque el Celta superó igualmente la eliminatoria, de hecho llegó a la final aquella campaña', 'historia', TRUE, NOW()),
  ('Tuvieron que pasar más de tres lustros para ver al Leganés en Balaídos, y fue precisamente en su debut en la máxima categoría, que estrenó a lo grande con otro triunfo por la mínima', 'historia', TRUE, NOW()),
  ('En las tres siguientes visitas, los resultados mejoraron para el Celta, aunque siempre con pocos goles', 'historia', TRUE, NOW()),
  ('Las dos únicas victorias fueron por la mínima (1-0); en la Temporada 2017-18 y en la 2019-20, en ambos casos con gol de Iago Aspas', 'historia', TRUE, NOW()),
  ('El partido de la campaña 2018-19 finalizó con empate sin goles', 'historia', TRUE, NOW()),
  ('Por lo tanto este es un que garantiza pocos goles, de hecho nunca ha habido más de uno, en una combinación binaria que hace de este partido una rara avis', 'historia', TRUE, NOW()),
  ('Veremos si el estilo atrevido de Claudio Giráldez se impone al más conservador de Borja Jiménez y vemos en esta ocasión más goles, y sobre todo del Celta.', 'historia', TRUE, NOW()),
  ('En los primeros años de la historia del Celta, cuando todavía no existía LaLiga, eran muy habituales los partidos amistosos que celebraban los equipos para llenar los huecos que quedaban libres cuando no disputaban los campeonatos regionales o la Copa, en caso de que lograsen clasificarse para esta competición', 'historia', TRUE, NOW()),
  ('También en aquella época eran bastante habituales los viajes de los clubes para disputar partidos en otros países', 'historia', TRUE, NOW()),
  ('El Celta viajó a Sudamérica en varias ocasiones, y también recibió a equipos de ese continente, entre ellos a Boca Juniors, que estos días celebró a través de su página web el centenario de su gira europea que comenzó en Vigo, con un partido ante el Celta en viejo campo de Coia. “Para esa jornada histórica, Boca formó así: Tesoriere, Bidoglio, Mutis, Médici, Vaccaro, Elli, Tarasconi, Cerrotti, Garasino, Seoane y Onzari', 'historia', TRUE, NOW()),
  ('Rápido llegó el primer gol a través de Antonio Cerrotti (cuyo verdadero nombre era Antonino Cerrotta), que de esa forma se transformó en el primer jugador argentino en marcar un tanto en el Viejo Continente', 'historia', TRUE, NOW()),
  ('Luego, el mismo delantero se encargó de ampliar la ventaja para el Xeneize', 'historia', TRUE, NOW()),
  ('Tras el descuento, Cesáreo Onzari convirtió el gol que selló la victoria por 3 a 1”, escribió el club argentino en su portal', 'historia', TRUE, NOW()),
  ('Boca Juniors se convertía en el primer club de América, incluso antes que la selección argnetina, en disputar un partido en Europa, el primero de una larga gira que convirtió al equipo Xeneize en uno de los más populares de su país en Europa.', 'historia', TRUE, NOW()),
  ('En esta sección colgaremos partidos completos o resúmenes de los grandes partidos que han marcado la historia de nuestra Celta, con especial énfasis en aquellos que nos hicieron grandes en Europa', 'historia', TRUE, NOW()),
  ('Liverpool, Juventus o Aston Villa fueron algunas de las víctimas del Euro- Celta', 'historia', TRUE, NOW()),
  ('CELTA 4- JUVENTUS 0 (UEFA 1999-00) null CELTA 3- LIVERPOOL 1 (UEFA 1998-99) null', 'historia', TRUE, NOW()),
  ('Foto: Atlántico Diario Fran Beltrán sigue haciendo historia en el Celta, y con el partido disputado el pasado sábado en Mendizorrotza alcanzó a una leyenda del celtismo como Vlado Gudelj en la lista de jugadores con más partidos oficiales disputados', 'historia', TRUE, NOW()),
  ('El de Seseña, al igual que el delantero bosnio, suman 258 entorchados con la camiseta celeste', 'historia', TRUE, NOW()),
  ('El centrocampista tiene por delante a 17 jugadores en una lista que sigue encabezada por Iago Aspas, que aumentó el récord a 539 ante el Alavés, y en la que el siguiente objetivo para Fran Beltrán es Fernando Cáceres, que ocupa la décimo séptima posición en la tabla histórica con 264 partidos', 'historia', TRUE, NOW()),
  ('Otros objetivos alcanzables para Fran Beltrán antes de que acabe el curso son Herminio (265), Mori (266), Pepe Villar (269), Gelo (277) y Villar (277)', 'historia', TRUE, NOW()),
  ('Más complicado parece que pueda alcanzar a Pichi Lucas (277), o a Mostovoi, que con 290 partidos ocupa la décima posición en el Ranking histórico', 'historia', TRUE, NOW()),
  ('Recordemos que Fran Beltrán concluye su contrato al final del presente curso y no está claro que pueda continuar', 'historia', TRUE, NOW()),
  ('En todo caso quedará en la historia, ya que recientemente superó al propio Mostovoi en la lista de jugadores con más partidos en Primera División, ocupando la tercera plaza solo por detrás de Hugo Mallo y Aspas.', 'historia', TRUE, NOW()),
  ('Manu Fernández fue una de las grandes sorpresas en la alineación inicial de Claudio Giráldez en Son Moix', 'historia', TRUE, NOW()),
  ('El técnico celeste confió en el canterano para ocupar el puesto de central por la derecha, brindándole la oportunidad de debutar en Primera División y de disputar su primer partido oficial con el Celta', 'historia', TRUE, NOW()),
  ('Más allá de lo deportivo, su presencia sobre el césped supuso un acontecimiento histórico: por primera vez, tres generaciones de una misma familia defendieron la camiseta del club vigués en competición oficial', 'historia', TRUE, NOW()),
  ('El pionero de la saga fue Manuel Fernández Amado , nacido en Ferrol el 14 de mayo de 1950', 'historia', TRUE, NOW()),
  ('Centrocampista de calidad y recorrido, militó en el Celta entre 1971 y 1975, periodo en el que disputó 114 encuentros oficiales y anotó 4 goles', 'historia', TRUE, NOW()),
  ('Fue pieza importante en la histórica campaña 1971-72, cuando el club disputó la Copa de la UEFA por primera vez en su historia', 'historia', TRUE, NOW()),
  ('Tras dejar Balaídos, prolongó su carrera en el Espanyol durante seis temporadas', 'historia', TRUE, NOW()),
  ('A él le siguió su hijo, Manel Fernández , nacido también en Ferrol, el 9 de mayo de 1972', 'historia', TRUE, NOW()),
  ('Formado en la cantera del Racing de Ferrol, llegó en 1992 al Celta B, donde permaneció dos cursos', 'historia', TRUE, NOW()),
  ('Con el filial dejó 18 goles en 60 partidos, y el 19 de diciembre de 1993 cumplió su sueño de debutar con el primer equipo: lo hizo en el Camp Nou frente al Barcelona, entrando en el minuto 67 en sustitución de Oliete', 'historia', TRUE, NOW()),
  ('Más tarde regresaría al Racing, donde consolidó su carrera con 234 partidos oficiales y 42 tantos', 'historia', TRUE, NOW()),
  ('La saga alcanzó su tercera generación con Manu Fernández Arroyo , nacido en Ferrol el 23 de abril de 2001', 'historia', TRUE, NOW()),
  ('Tras formarse en la cantera celeste y destacar las dos últimas temporadas en el Celta Fortuna, este curso le llegó el momento de dar el salto al primer equipo', 'historia', TRUE, NOW()),
  ('Su debut como titular en Son Moix no solo marcó el inicio de una nueva etapa en su carrera, sino también un hito histórico para su familia y para el Celta.', 'historia', TRUE, NOW()),
  ('Foto: Aitor Alcalde / Getty Images Aunque todavía no es matemático, con los tres puntos logrados ayer por el Celta en Mestalla, el equipo de Claudio Giráldez se ha asegurado la permanencia en Primera División, un objetivo que se daba por hecho desde hace varias semanas, pero que ya podemos celebrar con 44 puntos sin ningún tipo de temor a lo que pase en las últimas jornadas', 'historia', TRUE, NOW()),
  ('La distancia con respecto a la zona de descenso es de 15 puntos, con 24 en juego, por lo que será matemático en las próximas semanas. quedan ocho jornadas por delante para soñar con objetivos más ambiciosos, con la mirada puesta en seguir un año más en Europa, lo cual sería fantástico, incluso con el posible premio gordo de la Champions, que parecía imposible cuando comenzó la temporada, y sigue estando muy complicado, pero mucho más cerca de lo que todos hubiésemos sospechado', 'historia', TRUE, NOW()),
  ('Estar a un punto de la máxima competición continental a estas alturas de la temporada es algo que hubiese firmado hasta el más optimista de los celtistas', 'historia', TRUE, NOW()),
  ('Pero eso será otra historia, muy bonito y emocionante, que tendremos que vivir en lo que resta de temporada, con la seguridad y la tranquilidad de saber que el equipo seguirá un año más en Primera División', 'historia', TRUE, NOW()),
  ('Aquel día de junio de 2012, cuando celebremos el ascenso tras el simulacro de partido ante el Córdoba empezó una etapa en Primera División que ya forma parte de la historia del club después de batir el récord de temporadas consecutivas en la máxima categoría, marcado en 1959 después de 14 temporadas consecutivas en Primera División', 'historia', TRUE, NOW()),
  ('A finales del siglo pasado y comienzos del presente, el Celta vivió otro gran momento en el que parecía que esa cifra se iba a superar, pero el contador se paró en 12 justo después de alcanzar la clasificación para la Champions League', 'historia', TRUE, NOW()),
  ('Durante estos años han sido varias las temporadas en las que la permanencia pendió de un hilo durante gran parte del curso', 'historia', TRUE, NOW()),
  ('No ha faltado sufrimiento, pero a diferencia de época pretéritas, los finales han sido siempre felices', 'historia', TRUE, NOW()),
  ('Y también ha habido años muy buenos, como los últimos dos, que han hecho disfrutar y soñar al celtismo', 'historia', TRUE, NOW()),
  ('Estar en Primera División es prioritario, y estos 15 años en la máxima categoría son una bendición a muchos niveles, incluido a nivel social', 'historia', TRUE, NOW()),
  ('Hay chicos y chicas de 20 años que no recuerdan al Celta en Segunda División', 'historia', TRUE, NOW()),
  ('La masa social se ha incrementado de forma notable, y cada año de continuidad en Primera División sirve para solidificar los cimientos del futuro', 'historia', TRUE, NOW()),
  ('Sigamos disfrutando de esta travesía, de lo que queda de la temporada 60 en Primera y de lo que será la 61.', 'historia', TRUE, NOW()),
  ('Foto: Diogo Cardoso / Getty Images Ilaix Moriba cerró la temporada por todo lo alto', 'jugadores', TRUE, NOW()),
  ('El internacional guineano, que ya firmó un gran partido en San Mamés ante el Athletic, confirmó en la última jornada frente al Sevilla que llegó al final del curso en un gran estado de forma siendo el jugador más valorado por nuestros lectores tras anotar el único tanto del encuentro, que dio una victoria que le permitió al Celta confirmar su participación en la Europa League el próximo curso', 'jugadores', TRUE, NOW()),
  ('Por detrás del centrocampista se situó Andrei Radu, en su línea habitual de realizar grandes intervenciones que sostuvieron al equipo en los momentos más complicados, con una gran parada en la primera mitad cuando el Sevilla estaba teniendo las mejores ocasiones. la tercera plaza del podio de la jornada es para Javi Rueda, que volvió a ser un galgo por la banda derecha', 'jugadores', TRUE, NOW()),
  ('El Celta cerró el curso con una victoria que tuvo consecuencias en las notas de nuestros lectores, ya que ningún jugador céltico suspendió, siendo Pablo Durán con un 5,23 el que obtuvo la peor nota del encuentro. 1 Moriba 7,86 2 Radu 7,72 3 Javi Rueda 7,54 4 Carreira 7,26 5 Fer López 6,95 6 Yoel Lago 6,61 7 Iago Aspas 6,31 8 Marcos Alonso 6,20 9 Javi Rodríguez 6,19 10 Hugo Álvarez 6,17 11 Jutglà 6,15 12 Swedberg 6,14 13 Borja Iglesias 5,86 14 Vecino 5,38 15 Pablo Durán 5,23', 'jugadores', TRUE, NOW()),
  ('Matías Vecino ha sido el jugador más valorado por nuestros lectores en el partido de ida de la eliminatoria de octavos de final de la Europa League', 'jugadores', TRUE, NOW()),
  ('El uruguayo ocupó el mediocentro en lugar del lesionado Miguel Román, y tuvo una actuación destacada, participando de forma decisiva en la contra que originó el tanto del Celta', 'jugadores', TRUE, NOW()),
  ('Junto al recién llegado a Vigo también ocuparon puestos de podio dos defensas: Carl Starfelt, que sigue a un gran nivel en competición continental, y Javi Rueda, que anotó el tanto celeste', 'jugadores', TRUE, NOW()),
  ('Nuestros lectores también destacaron la actuación de Williot Swedberg, Javi Rodríguez y Marcos Alonso, que acabaron con una nota media superior al 7', 'jugadores', TRUE, NOW()),
  ('En la parte negativa destacar el único suspenso del partido, otorgado a Borja Iglesias, castigado por la expulsión que dejó al equipo con uno menos durante los últimos cuarenta minutos de partido. 1 Vecino 7,56 2 Starfelt 7,41 3 Javi Rueda 7,38 4 Swedberg 7,20 5 Javi Rodríguez 7,11 6 Marcos Alonso 7,00 7 Radu 6,55 8 Carreira 6,37 9 Mingueza 6,19 10 Pablo Durán 5,81 11 Moriba 5,61 12 Iago Aspas 5,56 13 Ristic 5,28 14 Jutglà 5,27 15 Borja Iglesias 4,27', 'jugadores', TRUE, NOW()),
  ('Borja Iglesias está en racha, alcanzando cifras muy pocas veces vistas en la historia del Celta', 'historia', TRUE, NOW()),
  ('El compostelano anotó ayer el gol que en ese momento ponía en ventaja al Celta, y lograba marcar por sexto partido consecutivo, algo que no hacía un jugador del Celta desde hace 78 años, según publica la cuenta de X Afouteza e Corazón , referente a nivel de estadísticas, datos y curiosidades del Celta', 'historia', TRUE, NOW()),
  ('El último céltico en lograrlo fue un tal Pahíño , uno de los mayores goleadores de LaLiga, y por supuesto del Celta', 'historia', TRUE, NOW()),
  ('Añadimos a la información de Afouteza e Corazón las fechas exactas de la racha del vigués, que comenzó el 21 de septiembre de 1947, en la primera jornada de Liga, con victoria del Celta (5-1) ante el Athletic en Balaídos, y finalizó el 2 de noviembre de 1947, en la sexta jornada del campeonato, en el empate a un gol ante el Barcelona, también en Balaídos, Eso sí, Pahíño anotó en esa racha ni más ni menos que 10 goles en esos 6 encuentros', 'historia', TRUE, NOW()),
  ('Aquella temporada Pahíño marcaría 31 goles en 32 partidos, contando todas las competiciones, y con 21 goles en Liga se convertiría en el Trofeo Pichichi, el único en la historia del Celta', 'historia', TRUE, NOW()),
  ('Su racha se acabó en el sexto partido, por lo tanto Borja Iglesias lo superará si marca el domingo ante el Atlético de Madrid', 'historia', TRUE, NOW()),
  ('Otro gran goleador en la historia del Celta, Hermidita , también tuvo una racha de seis partidos consecutivos, pero con un matiz, ya que lo logró en seis partidos suyos, pero no en 6 partidos del Celta', 'historia', TRUE, NOW()),
  ('Fue entre la jornada 18 y la 24 de la Temporada 1949-50, pero no participó en la jornada 19', 'historia', TRUE, NOW()),
  ('Foto: Diogo Cardoso / Getty Images El excéltico Brais Méndez es uno de los hombres que están sonando en los primeros días del mercado de fichajes, que todavía no está abierto pero dispara la rumorología tras el final de LaLiga', 'partidos', TRUE, NOW()),
  ('El extremo milita en la Real Sociedad desde hace cuatro años, cuando el Celta lo traspasó por unos 13 millones de euros', 'partidos', TRUE, NOW()),
  ('La falta de continuidad que ha tenido esta temporada, unida a su deseo de regresar y el del Celta de volver a tenerlo en su plantilla harán que se hable mucho de esta posibilidad durante todo el verano, aunque siendo honestos es complicado', 'partidos', TRUE, NOW()),
  ('Son muchos los aficionados del Celta que anhelan su vuelta, no todos evidentemente', 'partidos', TRUE, NOW()),
  ('Los que le pitaban cuando era jugador del Celta no se han evaporado, pero pese a todo creo que son mayoría aquellos que quieren que regrese', 'partidos', TRUE, NOW()),
  ('Y entre esos aficionados que desean su regreso está uno cuya opinión tiene bastante peso: Claudio Giráldez', 'partidos', TRUE, NOW()),
  ('En una entrevista concedida al diario As, el preparador del Celta reconoció que es un jugador que le gusta, aunque admitió no saber en qué punto está esta posibilidad: "No sé cómo está la situación actualmente', 'partidos', TRUE, NOW()),
  ('Ya he dicho que me gusta y que sabemos que le tiene un cariño increíble al club', 'partidos', TRUE, NOW()),
  ('Ojalá algún día pueda estar aquí ", subrayó, expresando más un deseo que una realidad a día de hoy.', 'partidos', TRUE, NOW()),
  ('Poco más de tres años después de llegar al Celta, Fran Beltrán vivió ayer su centenario como jugador céltico en un partido que empezó bien, pero que acabó complicándose en la segunda mitad, precisamente cuando el de Seseña saltó al terreno de juego, coincidiendo con la remontada blanca', 'estadio', TRUE, NOW()),
  ('Desde su debut con la camiseta celeste el 18 de agosto de 2018, en un encuentro disputado en Balaídos ante el Espanyol, Fran Beltrán ha disputado 94 partidos de Primera División y 6 de Copa del Rey, con un balance de 32 victorias, 27 empates y 41 derrotas', 'estadio', TRUE, NOW()),
  ('Durante este centenar de partidos ha anotado 5 goles, ha visto 9 tarjetas amarillas y ha sido expulsado en una ocasión, en la derrota frente al Granada de la cuarta jornada de la Temporada 2019-20', 'estadio', TRUE, NOW()),
  ('A sus 22 años es un futbolista que cuenta con una importante experiencia, desde su debut con el Rayo Vallecano en Segunda División en la Temporada 2016-17, y mucho futuro por delante', 'estadio', TRUE, NOW()),
  ('Le quedan dos años de contrato con el Celta, y se espera que en los próximos meses el club mueva ficha para ampliar su contrato, especialmente porque se trata de un jugador por el que han llegado propuestas interesantes a Príncipe.', 'estadio', TRUE, NOW()),
  ('Foto: RC Celta (EFE) Con su victoria frente al Valencia en Mestalla (2-3), el Celta de Claudio Giráldez igualó este domingo la mejor puntuación a domicilio de la historia en Primera División, los 27 puntos que firmara el conjunto dirigido entonces por Eduardo Berizzo en la temporada 2015-16', 'historia', TRUE, NOW()),
  ('Siete triunfos, seis empates y solo dos derrotas son los números del Celta en el presente curso liguero', 'historia', TRUE, NOW()),
  ('El Barcelona (31) y el Real Madrid (30) mejoran la puntuación celeste, pero ambos han sufrido más derrotas lejos de su estadio: tres los blancos y cuatro los azulgranas', 'historia', TRUE, NOW()),
  ('Por delante, el Celta de Giráldez todavía tiene cuatro partidos para mejorar el registro que firmó el equipo de Berizzo', 'historia', TRUE, NOW()),
  ('Eso sí, le esperan cuatro etapas pirenaicas, ya que visitará, de manera consecutiva, a Barcelona, Villarreal, Atlético de Madrid y Athletic Club', 'historia', TRUE, NOW()),
  ('El otro reto que le queda por delante es el de convertirse en el Celta con más victorias a domicilio en la máxima categoría', 'historia', TRUE, NOW()),
  ('Foto: La Voz de Galicia El 4 de marzo de 2001 el Real Oviedo visitaba Balaídos', 'historia', TRUE, NOW()),
  ('Era una visita rutinaria para disputar uno de los por entonces clásicos de LaLiga entre dos equipos que se habían enfrentando en 90 ocasiones a lo largo de la historia', 'historia', TRUE, NOW()),
  ('Dos rivales relativamente cercanos a nivel geográfico que cada año se citaban con puntualidad en el templo celeste y en el Tartiere', 'historia', TRUE, NOW()),
  ('Pocos imaginábamos por entonces que pasaría más de un cuarto de siglo hasta la siguiente visita del club carbayón', 'historia', TRUE, NOW()),
  ('El Real Oviedo bajó esa misma temporada a Segunda División, donde se agudizaron sus problemas económicos, comenzando una peregrinación por la Segunda B y la Tercera División, que llegaron a poner en duda incluso su viabilidad y supervivencia como club', 'historia', TRUE, NOW()),
  ('Afortunadamente lograron superar esa mala etapa y el pasado curso lograron el ansiado ascenso tras una larga travesía por el desierto de 24 años', 'historia', TRUE, NOW()),
  ('Aquel 4 de marzo se impuso el Celta al conjunto ovetense, dirigido desde el banquillo por Radomir Antic, que unos años después entrenaría de forma breve y poco exitosa al equipo celeste en su temporada de descenso', 'historia', TRUE, NOW()),
  ('Por el Celta jugaron aquel día Cavallero, Velasco, Berizzo, Cáceres, Juanfran, Gustavo López, Karpin, Mostovoi, Vagner, Giovanella y Catanha, siendo este último el autor del gol de la victoria por la mínima del Celta: 1-0', 'historia', TRUE, NOW()),
  ('En la segunda mitad también jugaron Edu, Jayo y Pinto, que entró a tres minutos del final en lugar del lesionado Pablo Cavallero', 'historia', TRUE, NOW()),
  ('El Real Oviedo formó de inicio con Esteban, que unos años después sería guardameta del Celta, Keita, Gaspar, Boris, Danjou, Martinovic, Tomic, Jaime, Iván Ania, Paunovic y Oli', 'historia', TRUE, NOW()),
  ('En la segunda parte entraron al terreno de juego Rubén Suárez, Raúl García, y Stan Collymore', 'historia', TRUE, NOW()),
  ('En el banquillo ovetense estuvo aquel día Juan Carlos Unzué, posteriormente entrenador del Celta en dos etapas, una como ayudante de Luis Enrique, y otra, más reciente, como entrenador jefe del Celta.', 'historia', TRUE, NOW()),
  ('Foto: José Manuel Rey Álvarez / Getty Images (EFE) Con su empate ante la Real Sociedad (1-1), el Celta de Claudio Giráldez estableció un nuevo récord negativo en la historia del club vigués, que nunca antes había tardado más de nueve jornadas en celebrar una victoria en LaLiga', 'historia', TRUE, NOW()),
  ('El equipo celeste superó este domingo el registro de la temporada 1956-57, cuando el conjunto dirigido entonces por el argentino Alejandro Scopelli goleó al Jaén (4-0) en la novena jornada de aquel campeonato', 'historia', TRUE, NOW()),
  ('El Celta, además, es el equipo con más empates (7) de las cinco mejores ligas europeas', 'historia', TRUE, NOW()),
  ('Todos ellos fueron con el mismo resultado (1-1), lo que le convierte en el primer equipo de LaLiga que repite el mismo resultado en siete de las primeras nueve jornadas', 'historia', TRUE, NOW()),
